void RequestManager::onFrame(Frame &frame) {
    FrameFactory &factory = frame.isPreview ? static_cast<FrameFactory &>(previewFactory_)
                                            : static_cast<FrameFactory &>(captureFactory_);
    int ret = factory.runPipes(frame);
    if (ret >= 0) {
        sendResult(frame);
    }
    onFrameDone(frame);
}

